-- Тема 10: варианты ответов выровнены по длине и форме (40 исправлений в 15 вопросах), ключи не меняются.
-- Источник: scripts/questions/074_option_length_topic10.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('option', 'Для чего служат табличные пространства?', 'Ограничивают права пользователей', 'Ограничивают права пользователей на объекты', 'Права задаются привилегиями.', NULL),
        ('option', 'Для чего служат табличные пространства?', 'Разделяют базы по кодировке', 'Разделяют базы данных по кодировке символов', 'Кодировка задаётся для базы данных.', NULL),
        ('option', 'Для чего служат табличные пространства?', 'Определяют физическое расположение данных в файловой системе', 'Задают, в каком каталоге лежат файлы данных', 'По сути, это указание на каталог.', 'Табличное пространство определяет физическое расположение данных в файловой системе: по сути это указание на каталог.'),
        ('option', 'Какие табличные пространства создаются при инициализации кластера?', 'pg_data и pg_wal', 'pg_data, pg_wal и pg_xact', 'Это не табличные пространства; pg_wal — каталог журнала.', NULL),
        ('option', 'Что хранится в табличном пространстве pg_global?', 'Объекты шаблона template1', 'Объекты шаблонной базы template1 и template0', 'Объекты template1 изначально лежат в pg_default.', NULL),
        ('option', 'Что хранится в табличном пространстве pg_global?', 'Временные таблицы', 'Временные таблицы всех баз данных кластера', 'Временные таблицы — в явно указанном ТП, в temp_tablespaces или в ТП базы по умолчанию.', NULL),
        ('option', 'Что хранится в табличном пространстве pg_global?', 'Общие для кластера объекты системного каталога', 'Общие объекты каталога всего кластера', 'Например, базы данных, роли и табличные пространства.', 'Общие для кластера объекты системного каталога: например, базы данных, роли и табличные пространства.'),
        ('option', 'Что хранится в табличном пространстве pg_global?', 'Журнал предзаписи', 'Журнал предзаписи и архив сегментов WAL', 'Журнал находится в PGDATA/pg_wal.', NULL),
        ('option', 'Что PostgreSQL создаёт в PGDATA/pg_tblspc для пользовательского табличного пространства?', 'Копию данных', 'Копию его данных для быстрого доступа', 'Данные хранятся в каталоге ТП, без копий.', NULL),
        ('option', 'Что PostgreSQL создаёт в PGDATA/pg_tblspc для пользовательского табличного пространства?', 'Файл конфигурации', 'Файл конфигурации с параметрами ТП', 'Отдельный файл не создаётся; параметры ТП хранятся в pg_tablespace.', NULL),
        ('option', 'Что PostgreSQL создаёт в PGDATA/pg_tblspc для пользовательского табличного пространства?', 'Архив WAL', 'Отдельный архив WAL для его объектов', 'Архив WAL с табличными пространствами не связан.', NULL),
        ('option', 'Зачем внутри каталога пользовательского ТП есть подкаталог с версией сервера?', 'Для хранения журнала', 'Для хранения журнала этой версии сервера', 'Журнал в табличном пространстве не хранится.', NULL),
        ('option', 'Зачем внутри каталога пользовательского ТП есть подкаталог с версией сервера?', 'Это имя базы данных', 'Это имя базы данных внутри кластера', 'Подкаталоги баз находятся уже внутри него.', NULL),
        ('option', 'Может ли одна база данных хранить объекты в нескольких табличных пространствах?', 'Нет, только в одном', 'Нет, все объекты базы лежат в одном ТП', 'Можно и в нескольких.', NULL),
        ('option', 'Может ли одна база данных хранить объекты в нескольких табличных пространствах?', 'Да: у базы есть ТП по умолчанию, а отдельные объекты можно размещать в других', 'Да, объекты можно размещать в разных ТП', 'Место хранения указывают при создании объекта.', 'У базы есть табличное пространство по умолчанию, а для отдельных объектов место хранения указывают при создании.'),
        ('option', 'Может ли одна база данных хранить объекты в нескольких табличных пространствах?', 'Только если её владелец — суперпользователь', 'Да, если её владелец — суперпользователь', 'Владелец базы здесь роли не играет.', NULL),
        ('option', 'Может ли одна база данных хранить объекты в нескольких табличных пространствах?', 'Только временные объекты', 'Да, для временных объектов, но не для постоянных', 'В других ТП можно размещать и постоянные таблицы, и индексы.', NULL),
        ('option', 'Где хранятся объекты системного каталога конкретной базы данных?', 'Всегда в pg_global', 'В pg_global вместе с общими объектами', 'В pg_global только общие для кластера объекты.', NULL),
        ('option', 'Какое табличное пространство становится ТП по умолчанию для новой базы, если TABLESPACE не указан?', 'Всегда pg_global', 'pg_global, общее для всего кластера', 'pg_global только для общих объектов.', NULL),
        ('option', 'Какое табличное пространство становится ТП по умолчанию для новой базы, если TABLESPACE не указан?', 'Всегда последнее созданное', 'Последнее созданное табличное пространство', 'Порядок создания табличных пространств роли не играет.', NULL),
        ('option', 'Какое табличное пространство становится ТП по умолчанию для новой базы, если TABLESPACE не указан?', 'То же, что у шаблона, из которого клонируется база', 'Табличное пространство базы-шаблона', 'База получает табличное пространство шаблона.', 'База получает табличное пространство шаблона, из которого она клонируется.'),
        ('option', 'Какое табличное пространство становится ТП по умолчанию для новой базы, если TABLESPACE не указан?', 'База создаётся без ТП по умолчанию', 'Никакое: база создаётся без ТП по умолчанию', 'У базы всегда есть табличное пространство по умолчанию.', NULL),
        ('option', 'Какой сценарий типичен для табличных пространств?', 'Архивные данные на медленных дисках, активные — на быстрых', 'Архив — на медленных дисках, активные — на быстрых', 'Данные размещаются на дисках разной скорости.', NULL),
        ('option', 'Какой сценарий типичен для табличных пространств?', 'Разделение прав между пользователями', 'Разделение прав между разными пользователями', 'Права задаются привилегиями.', NULL),
        ('option', 'Какой сценарий типичен для табличных пространств?', 'Хранение разных версий одной таблицы', 'Хранение старых версий строк отдельно от таблицы', 'Версии строк лежат в той же таблице.', NULL),
        ('option', 'Какой сценарий типичен для табличных пространств?', 'Ускорение репликации', 'Ускорение физической репликации на реплики', 'К репликации это не относится.', NULL),
        ('option', 'Что верно для табличного пространства по умолчанию баз данных, созданных при инициализации кластера?', 'При стандартных настройках в нём создаются объекты, если табличное пространство не указано явно', 'В нём создаются объекты, если ТП не указано явно', 'Если не указано другое и не задан default_tablespace.', 'При стандартных настройках: если не указано другое и не задан default_tablespace.'),
        ('option', 'Что верно для табличного пространства по умолчанию баз данных, созданных при инициализации кластера?', 'Оно всегда совпадает с pg_global', 'Оно совпадает с табличным пространством pg_global', 'pg_global — для общих объектов кластера.', NULL),
        ('option', 'Что верно для табличных пространств?', 'Табличное пространство нельзя удалить', 'Табличное пространство нельзя удалить командой SQL', 'Пустое табличное пространство удаляет DROP TABLESPACE.', NULL),
        ('option', 'Что верно для табличных пространств?', 'Одна база может хранить объекты в нескольких табличных пространствах', 'Одна база может хранить объекты в разных ТП', 'Отдельные объекты можно размещать в других ТП.', NULL),
        ('option', 'Что верно для табличных пространств?', 'Схема и табличное пространство — одно и то же', 'Схема и табличное пространство — одно и то же понятие', 'Схема — логическое понятие, табличное пространство — физическое.', NULL),
        ('option', 'Где на диске находятся стандартные табличные пространства?', 'Пользовательские — всегда внутри PGDATA/base', 'Пользовательские — внутри PGDATA/base', 'Каталог пользовательского ТП задаётся в LOCATION, обычно вне PGDATA; в pg_tblspc на него ссылка.', NULL),
        ('option', 'Что нужно, чтобы удалить табличное пространство командой DROP TABLESPACE?', 'Остановить сервер', 'Остановить сервер на время удаления', 'Команда выполняется на работающем сервере.', NULL),
        ('option', 'Что нужно, чтобы удалить табличное пространство командой DROP TABLESPACE?', 'Удалить все базы кластера', 'Сначала удалить все базы данных кластера', 'Достаточно, чтобы в этом пространстве не было объектов.', NULL),
        ('option', 'Почему внутри PGDATA/global нет подкаталогов баз данных?', 'Данные в нём относятся ко всему кластеру, а не к отдельным базам', 'Его данные относятся ко всему кластеру, а не к базам', 'Это табличное пространство pg_global с общими объектами каталога.', NULL),
        ('option', 'Почему внутри PGDATA/global нет подкаталогов баз данных?', 'Подкаталоги создаются только после первого подключения', 'Подкаталоги появляются после первого подключения', 'Такой зависимости нет.', NULL),
        ('option', 'Что задают параметры seq_page_cost и random_page_cost?', 'Размер буферного кеша', 'Размер буферного кеша для разных видов чтения', 'Это параметр shared_buffers.', NULL),
        ('option', 'Что задают параметры seq_page_cost и random_page_cost?', 'Стоимость хранения данных на диске', 'Стоимость хранения страницы данных на диске', 'Речь об оценке стоимости чтения, а не хранения.', NULL),
        ('option', 'Что задают параметры seq_page_cost и random_page_cost?', 'Примерную стоимость чтения страницы при последовательном и произвольном доступе — для планировщика', 'Оценку стоимости чтения страницы для планировщика', 'Их можно задать и для отдельного табличного пространства.', 'Примерную стоимость чтения страницы при последовательном и произвольном доступе; их можно задать и для отдельного табличного пространства.'),
        ('option', 'Что задают параметры seq_page_cost и random_page_cost?', 'Предельную скорость чтения с диска', 'Предельную скорость чтения с диска сервером', 'Параметры меняют только оценки планировщика, а не работу дисков.', NULL)
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
